import java.io.*;
import java.util.*;

public class Main {
    static int mod = (int)(Math.pow(10, 9) + 7);
    public static void main(String[] args) {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            String[] parts = br.readLine().split(" ");
            long n = Long.parseLong(parts[0]);
            long m = Long.parseLong(parts[1]);
            if (m < n) {
                long temp = n;
                n = m;
                m = temp;
            }
            if (n <= 2 && m <= 2) {
                out.println(0);
            } else if (n == 1) {
                long res = (m / 6) * 6;
                long rem = m % 6;
                if (rem >= 4) {
                    rem -= 3;
                    res += rem * 2;
                }
                out.println(res);
            } else if (n == 2) {
                long res = n * m;
                if (m == 3) res = 4;
                else if (m == 7) res = 12;
                out.println(res);
            } else {
                out.println((n * m) / 2 * 2);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        out.close();
    }
}
